import RNA, random, time, sys, multiprocessing as mp

target = "((..(((((........(.((..((.(.....(....).((((((((.........((......((((.....))))......))...((..((.......(..(......)..)..((..((.....((....)).((((.....(((.....(..((.(...).))..).....))).((((...(.......(..(.((...)).)..).......)...))))........)))).....((((((...)))))).))..))...........))..)).........(..((((....))((((((.....(........).....))))))..))..)...))))))))........).))..)).).....(.......).)))))..))."
N=len(target)
seed = ""

stack=[]; pairs=[]
for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop(); pairs.append((j,i))
partner={}
for (i,j) in pairs:
    partner[i]=j; partner[j]=i

def dist(s):
    return RNA.bp_distance(RNA.fold_compound(s).mfe()[0], target)

def worker(args):
    seed_seq, sid = args
    random.seed(sid)
    cur=seed_seq; cur_d=dist(cur)
    best=cur; best_d=cur_d
    deadline=time.time()+30
    while time.time()<deadline and best_d>0:
        c=list(cur)
        for _ in range(random.choice([1,1,1,2,2,3])):
            i=random.randrange(N)
            if i in partner:
                j=partner[i]
                new=random.choice(['G','C','A','U'])
                c[i]=new
                comp={'G':'C','C':'G','A':'U','U':'A'}
                c[j]=comp[new]
            else:
                c[i]=random.choice('ACGU')
        c=''.join(c)
        d=dist(c)
        if d < cur_d or (d==cur_d and random.random()<0.4):
            cur=c; cur_d=d
            if d<best_d:
                best=c; best_d=d
    return (best_d, best)

if __name__=='__main__':
    base_d=dist(seed)
    print("base",base_d, file=sys.stderr)
    args=[(seed,i) for i in range(200)]
    with mp.Pool(32) as p:
        results=p.map(worker, args)
    results.sort(key=lambda x:x[0])
    print("top5:",[r[0] for r in results[:5]], file=sys.stderr)
    print(results[0][0])
    print(results[0][1])
